#!/usr/bin/env swift

import EventKit
import CoreLocation
import Foundation

// === Configuration ===
let reminderTitle    = "Follow-up reminder (6 hrs after Lunch with Jordan)"
let timestamp        = 1788291000.0  // Sep 1, 2026, 7:30 PM UTC
let latitude         = 37.7749
let longitude        = -122.4194
let locationName     = "San Francisco, CA"
let locationRadius   = 100.0  // meters (geofence radius)
// =====================

let eventStore = EKEventStore()
let semaphore  = DispatchSemaphore(value: 0)

// Request access to Reminders
if #available(macOS 14.0, *) {
    eventStore.requestFullAccessToReminders { granted, error in
        defer { semaphore.signal() }
        guard granted, error == nil else {
            print("❌ Access denied: \(error?.localizedDescription ?? "Unknown error")")
            return
        }
        createReminder(in: eventStore)
    }
} else {
    eventStore.requestAccess(to: .reminder) { granted, error in
        defer { semaphore.signal() }
        guard granted, error == nil else {
            print("❌ Access denied: \(error?.localizedDescription ?? "Unknown error")")
            return
        }
        createReminder(in: eventStore)
    }
}

semaphore.wait()

func createReminder(in store: EKEventStore) {
    let reminder = EKReminder(eventStore: store)

    // Title
    reminder.title = reminderTitle

    // Calendar (default Reminders list)
    reminder.calendar = store.defaultCalendarForNewReminders()

    // Due date from timestamp
    let dueDate = Date(timeIntervalSince1970: timestamp)
    let components = Calendar.current.dateComponents(
        [.year, .month, .day, .hour, .minute, .second, .timeZone],
        from: dueDate
    )
    reminder.dueDateComponents = components

    // Time-based alarm
    let alarm = EKAlarm(absoluteDate: dueDate)
    reminder.addAlarm(alarm)

    // Location-based alarm (geofence)
    let location = EKStructuredLocation(title: locationName)
    location.geoLocation = CLLocation(latitude: latitude, longitude: longitude)
    location.radius = locationRadius

    let locationAlarm  = EKAlarm()
    locationAlarm.structuredLocation = location
    locationAlarm.proximity = .arrive  // trigger on arrival
    reminder.addAlarm(locationAlarm)

    // Save
    do {
        try store.save(reminder, commit: true)
        print("✅ Reminder created successfully!")
        print("   Title:    \(reminderTitle)")
        print("   Due:      \(dueDate)")
        print("   Location: \(locationName) (\(latitude), \(longitude))")
    } catch {
        print("❌ Failed to save reminder: \(error.localizedDescription)")
    }
}

